"""Read-only review of the exact November 5 archived aggressive selections."""
import csv,hashlib,json,math,sys
from collections import Counter
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from nba_quant.line_diagnostics import exposure_decomposition
from nba_quant.sgp import wilson
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'output/review-2026-11-05'

def main():
 target=ROOT/'output/polymarket/aggressive-tonight-2026-11-05.json';raw=target.read_bytes();frozen=json.loads(raw);manifest=json.loads((D/'manifest.json').read_text())
 assert hashlib.sha256(raw).hexdigest()==manifest['target_sha256']
 unique={};families=[]
 for bundle in frozen['games']:
  box=manifest['games'][bundle['game_id']];assert box['completed'] and box['canonical_status']=='VALIDATED_FINAL'
  assert hashlib.sha256(Path(box['source']['raw_path']).read_bytes()).hexdigest()==box['source']['sha256']
  for family in bundle['families']:
   legs=[]
   for leg in family['legs']:
    key=(bundle['game_id'],leg['player_id'],leg['stat'],leg['side'],leg['line'])
    matches=[p for p in box['players'] if p['id']==leg['player_id'] and p['team_id']==leg['team_id']];assert len(matches)==1
    actual=matches[0];assert not actual['row_flags'] and not actual['did_not_play']
    count=actual['stats'][leg['stat']];assert count is not None
    hit=count>leg['line'] if leg['side']=='over' else count<leg['line'] if leg['side']=='under' else count>=leg['line']
    status='PASS' if hit else 'FAIL';legs.append({'key':key,'status':status})
    if key not in unique:
     ask=leg['offer']['best_ask'];bid=leg['offer'].get('orderbook',{}).get('best_bid');spread=ask-bid if bid is not None else None
     k=leg['descriptive']['hits'];n=leg['descriptive']['games'];proxy=leg['aggressive_evidence']['proxy_probability'];lower=wilson(k,n)[0]
     fee_schedule=leg['offer'].get('fee_schedule');fee=None
     if leg['offer'].get('fees_enabled') is False:fee=0.
     elif fee_schedule and fee_schedule.get('exponent')==1 and fee_schedule.get('takerOnly') is True:fee=fee_schedule['rate']*ask*(1-ask)
     fee_cost=ask+fee if fee is not None else None
     clip=lambda p:min(1-1e-12,max(1e-12,p))
     loss=lambda p:-(int(hit)*math.log(clip(p))+(1-int(hit))*math.log(1-clip(p)))
     decomp=exposure_decomposition(leg['historical_distribution']['mean'],leg['minutes']['mean'],count,actual['stats']['minutes'])
     unique[key]={'game':box['game'],'game_id':box['id'],'player_id':leg['player_id'],'player':leg['player_name'],'stat':leg['stat'],'side':leg['side'],'line':leg['line'],'actual':count,'result':status,'family_sizes':[],
      'actual_minutes':actual['stats']['minutes'],'historical_mean':leg['historical_distribution']['mean'],'historical_minutes':leg['minutes']['mean'],'historical_hits':k,'historical_games':n,'proxy_probability':proxy,'saved_ask':ask,'saved_bid':bid,'spread':spread,'american_odds_at_selection':leg['offer']['american_odds'],'gross_proxy_return':leg['aggressive_evidence']['proxy_return_gross'],'known_entry_fee_per_share':fee,'entry_fee_adjusted_proxy_return':proxy/fee_cost-1 if fee_cost else None,'wilson_lower_fixed_threshold':lower,'wilson_lower_gross_proxy_return':lower/ask-1,'proxy_brier':(proxy-int(hit))**2,'ask_baseline_brier':(ask-int(hit))**2,'proxy_logloss':loss(proxy),'ask_baseline_logloss':loss(ask),'exposure_decomposition':decomp,'quote_observed_at':leg['offer']['observed_at'],'source_url':box['source_url'],'selection_basis':leg['selection_basis'],'availability':leg['availability']}
    unique[key]['family_sizes'].append(family['leg_count'])
   families.append({'game':box['game'],'game_id':box['id'],'size':family['leg_count'],'result':'BLOCKED_NO_TICKET' if not legs else 'MISS' if any(p['status']=='FAIL' for p in legs) else 'HIT','passed':sum(p['status']=='PASS' for p in legs),'selected_legs':len(legs)})
 rows=list(unique.values());assert len(rows)==8
 independent=json.loads((D/'independent-grading.json').read_text());im={(p['game_id'],p['player_id'],p['stat'],p['side'],p['line']):p for p in independent['unique_legs']}
 for key,row in unique.items():assert (row['actual'],row['result'])==(im[key]['actual'],im[key]['status'])
 avg=lambda key:sum(r[key] for r in rows)/len(rows)
 metrics={'unique_selections':8,'pass':sum(r['result']=='PASS' for r in rows),'fail':sum(r['result']=='FAIL' for r in rows),'printed_entries':sum(len(r['family_sizes']) for r in rows),'family_counts':dict(Counter(f['result'] for f in families)),'proxy_brier':avg('proxy_brier'),'ask_baseline_brier':avg('ask_baseline_brier'),'half_probability_reference_brier':.25,'proxy_logloss':avg('proxy_logloss'),'ask_baseline_logloss':avg('ask_baseline_logloss'),'half_probability_reference_logloss':math.log(2),'mean_proxy_probability':avg('proxy_probability'),'mean_ask_baseline':avg('saved_ask'),'wilson_lower_gross_positive_selected':sum(r['wilson_lower_gross_proxy_return']>0 for r in rows),'net_profit':None,'realized_roi':None}
 result={'date':'2026-11-05','source_as_of':manifest['acquired_at'],'original_target_sha256':hashlib.sha256(raw).hexdigest(),'metrics':metrics,'families':families,'lines':rows,'scope':'Eight unique selections in one game. Original overlapping families are alternatives, not independent observations. Prices are archived pregame asks, not current quotes or proof of placed bets.','limits':['No account bet ledger, combined parlay quote, stakes or actual fee/fill receipts exist, so account P&L and ROI are unavailable.','Beta historical proxy and quoted ask baseline scores are descriptive on one selected game, not independent calibration or long-run profitability evidence.','Wilson lower-bound sensitivity is outcome-free on frozen inputs, but naive intervals do not adjust for threshold search; it is not a certified replacement model.','Minutes/rate identity is accounting, not a causal matchup or coaching diagnosis.','Fee arithmetic uses archived exponent=1/rate=.05 parameters and currently documented entry-charge formula; excludes rebates, exit fees, gas and subsequent slippage. No trade is assumed.']}
 (D/'performance-review.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
 fields=['player','stat','side','line','actual','result','family_sizes','historical_hits','historical_games','historical_mean','actual_minutes','historical_minutes','proxy_probability','saved_ask','saved_bid','spread','american_odds_at_selection','gross_proxy_return','known_entry_fee_per_share','entry_fee_adjusted_proxy_return','wilson_lower_gross_proxy_return']
 with (D/'all-selected-lines.csv').open('w',newline='',encoding='utf-8-sig') as stream:
  writer=csv.DictWriter(stream,fieldnames=fields,extrasaction='ignore');writer.writeheader();writer.writerows(rows)
 lines=['# November 5 aggressive picks: final assessment','',f"Final sources checked {manifest['acquired_at']}. Original target hash {result['original_target_sha256']}.",'','Result: 0/3 nonempty families won; 4/8 distinct selections hit. Magic/Phoenix three families were blocked, not losses. Heat/Warriors 3-leg 1/3; 5-leg 3/5; 8-leg 4/8. Golden State 120, Miami 100. Phoenix 117, Orlando 104.','', '| Selection | Actual | Result | Prior hits | Original American |','|---|---:|---|---|---:|']
 for r in rows:lines.append(f"| {r['player']} {r['side']} {r['line']:g} {r['stat']} | {r['actual']} | {r['result']} | {r['historical_hits']}/{r['historical_games']} | {r['american_odds_at_selection']:+.0f} |")
 lines+=['','## What went right','', '- Exact market, team, player and source identity preserved. Four higher-priced legs hit, including Curry six made threes, Giannis fourteen rebounds, Melton six rebounds, and Green under 4.5 points (actual two).','- Orlando/Phoenix remained blocked by its evidence gate; unselected candidates are not retroactively treated as bets.','- Original selections and pregame prices remain unchanged.','', '## What went wrong','', '- I overcorrected toward larger payouts. A Beta(1,1) update on five to seven conditional-on-playing appearances was used as a probability proxy, then multiplied by a large decimal price and maximized. This does not establish a trained matchup-sensitive edge.','- The top three gross proxy returns exceeded 100%. Such large differences from the quoted market need investigation, not confidence based on a handful of games. The saved candidate ladders tested hundreds of choices on the same samples, increasing selection optimism.','- All three families shared the same losing Mitchell assists and Lendeborg points selections. They are highly overlapping alternatives, not three independent tests.','- Every selected player had UNVERIFIED game-specific availability. Morning quotes were fresh at construction, but the scan preceded tipoff by roughly fourteen hours; projected minutes, lineups and role changes were not refreshed in these frozen drafts.','- Entry fees and wide bid/ask spreads were not incorporated into candidate ranking. Bam had only +1.01% gross proxy return, an 81-cent spread, and no meaningful uncertainty margin. Its known entry fee reduces the proxy return to about +0.41%, not below zero; fees alone do not explain the loss.','', '## Math changes to validate next','', '1. Estimate minutes/role scenarios and stat-specific count distributions. Made threes need attempts and conversion modeled separately; do not treat a binary recent hit rate as a fitted tail probability.','2. Shrink small samples toward a defensible market/league baseline with prior strength fitted only on earlier dates. Beta(1,1) shrinks toward 50%, which can increase longshot proxy probabilities.','3. Rank fee-adjusted return and uncertainty, not the largest payout times a weak point estimate. For a $1-winning share at ask a, cost is a + r*a*(1-a) with the archived exponent-one fee schedule. Net entry proxy is p/cost-1. Require source-depth/freshness and assess spread as a liquidity-quality issue without subtracting spread twice from an ask-based cost.','4. Use an uncertainty-sensitive challenger as a diagnostic, not a post-hoc cure. Only two of the original eight selected lines had positive Wilson-lower gross proxy arithmetic. The full candidate pool then could not construct any 3/5/8 families. Abstention is allowed; this does not prove the challenger will make money.','5. Model joint dependence before presenting ticket probabilities or value, and expose shared-leg concentration. No combined price means no verified SGP EV.','6. Compare the full selection pipeline on untouched later dates using unique legs, Brier/log loss, fee-adjusted fills and game-clustered ticket outcomes. Keep November 5 as development evidence, not both training and proof of improvement.','', '## Proper score diagnostics','',f"Unique selected proxy Brier: {metrics['proxy_brier']:.6f}; archived-ask baseline {metrics['ask_baseline_brier']:.6f}; 50% reference .250000. Proxy log loss {metrics['proxy_logloss']:.6f}; ask baseline {metrics['ask_baseline_logloss']:.6f}; 50% reference {math.log(2):.6f}. These are eight dependent selections in one game. Ask is an execution cost, not an established fair probability. No long-run superiority or calibration conclusion is supported.",'', '## Every-line accounting']
 for r in rows:
  d=r['exposure_decomposition'];lines+=['',f"### {r['player']} - {r['result']}",'',f"Historical mean {r['historical_mean']:.3f}; actual {r['actual']}. Minutes prior {r['historical_minutes']:.3f}, actual {r['actual_minutes']}. Delta {d['total_difference']:+.3f} = minutes component {d['exposure_component']:+.3f} + realized-rate component {d['rate_component']:+.3f}.",f"Ask {r['saved_ask']}, bid {r['saved_bid']}, spread {r['spread']:.3f}; frozen gross proxy {r['gross_proxy_return']:.3%}, fee-adjusted entry proxy {r['entry_fee_adjusted_proxy_return']:.3%}. These remain uncalibrated model proxies, not realized returns."]
 lines+=['','## Sources','', 'https://www.espn.com/nba/boxscore/_/gameId/401909937','https://www.espn.com/nba/boxscore/_/gameId/401909936','https://docs.polymarket.com/trading/fees','']+['- '+l for l in result['limits']]
 (D/'PERFORMANCE_REVIEW.md').write_text('\n'.join(lines),encoding='utf-8')
 print(json.dumps(metrics,indent=2))
if __name__=='__main__':main()
